-- stochastic-processes implementation for BootstrapEstimator
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.

local Module = {}
function Module.Mean(samples)
    assert(#samples>0,"sample cannot be empty"); local total=0; for _,v in ipairs(samples) do total+=v end; return total/#samples
end
function Module.Resample(samples,indices)
    assert(#samples>0,"sample cannot be empty"); local result=table.create(#indices)
    for i,index in ipairs(indices) do assert(index>=1 and index<=#samples and index%1==0,"bootstrap index out of range"); result[i]=samples[index] end
    return result
end

return Module
